const items = [];

for (const item of $input.all()) {
  // Sonnet 5 adaptive thinking can interleave: text, more thinking, more
  // text. Gather ALL text blocks and pick the first candidate that contains
  // parseable JSON — joined first, then individual blocks longest-first.
  const blocks = (item.json.content || [])
    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text);
  const parseable = (t) => {
    try {
      const s = t.indexOf('{');
      const e = t.lastIndexOf('}');
      if (s === -1 || e <= s) return false;
      JSON.parse(t.substring(s, e + 1));
      return true;
    } catch (err) { return false; }
  };
  const candidates = [blocks.join(''), ...[...blocks].sort((a, b) => b.length - a.length)];
  const claudeResponse = candidates.find(parseable) || blocks.join('');

  try {
    // Handle mixed text+JSON responses and strip Markdown formatting
    let jsonContent = claudeResponse;
    const jsonStart = claudeResponse.indexOf('{');
    const jsonEnd = claudeResponse.lastIndexOf('}');

    if (jsonStart !== -1 && jsonEnd !== -1) {
      // Extract only what is strictly inside the first { and last }
      jsonContent = claudeResponse.substring(jsonStart, jsonEnd + 1);
    }

    const parsedContent = JSON.parse(jsonContent);

    // Completeness check: valid JSON that is missing required fields is a
    // failure, not a success — route it to the alert path with specifics.
    const REQUIRED_KEYS = ['cosmic_overview','collective_guidance','manifestation_focus',
      'timing_wisdom','aries','taurus','gemini','cancer','leo','virgo','libra','scorpio',
      'sagittarius','capricorn','aquarius','pisces','spiritual_practice'];
    const missing = REQUIRED_KEYS.filter((k) => typeof parsedContent[k] !== 'string' || !parsedContent[k].trim());
    if (missing.length > 0) {
      throw new Error('Incomplete daily content — missing: ' + missing.join(', '));
    }

    // v8.5: soft-validate the reel script \u2014 a bad reel must never sink the daily posts.
    const reel = parsedContent.reel_manifestation;
    const reelOk = reel && typeof reel === 'object'
      && typeof reel.hook === 'string' && reel.hook.trim()
      && Array.isArray(reel.beats) && reel.beats.length >= 3
      && reel.beats.every((b) => typeof b === 'string' && b.trim())
      && typeof reel.cta === 'string' && reel.cta.trim()
      && typeof reel.caption === 'string' && reel.caption.trim();
    if (!reelOk) { parsedContent.reel_manifestation = null; }

    // Add enhanced metadata
    const enhancedData = {
      ...parsedContent,
      generation_timestamp: new Date().toISOString(),
      content_type: "enhanced_daily_horoscopes",
      quality_indicators: {
        uses_intimate_language: true,
        includes_emotional_depth: true,
        addresses_real_situations: true,
        provides_actionable_guidance: true
      }
    };

    items.push({ json: enhancedData });

  } catch (error) {
    items.push({ 
      json: { 
        error: "Daily parsing failed",
        error_details: error.message,
        raw_response: String(claudeResponse || '(no text block in response)').substring(0, 1000),
        stop_reason: item.json.stop_reason || 'unknown',
        text_block_count: blocks.length,
        block_lengths: blocks.map((b) => b.length).join(',')
      } 
    });
  }
}

return items;

const items = [];
const seed = $('Cosmic Seed').first().json;

for (const item of $input.all()) {
  const horoscopes = item.json;

  // Get formatted date
  const today = new Date().toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });

  const signs = ['aries', 'taurus', 'gemini', 'cancer', 'leo', 'virgo', 
                'libra', 'scorpio', 'sagittarius', 'capricorn', 'aquarius', 'pisces'];

  // Helper function for zodiac emojis
  function getSignEmoji(sign) {
    const emojis = {
      aries: '♈', taurus: '♉', gemini: '♊', cancer: '♋',
      leo: '♌', virgo: '♍', libra: '♎', scorpio: '♏',
      sagittarius: '♐', capricorn: '♑', aquarius: '♒', pisces: '♓'
    };
    return emojis[sign] || '⭐';
  }

  // Safe property access with fallbacks
  const safeGet = (obj, path, fallback = '') => {
    try {
      return path.split('.').reduce((current, key) => current && current[key], obj) || fallback;
    } catch (e) {
      return fallback;
    }
  };

  // Extract data with fallbacks for the new raw persona
  const generalTheme = safeGet(horoscopes, 'cosmic_overview', 'Today brings heavy but clear energy.');
  const collectiveMessage = safeGet(horoscopes, 'collective_guidance', safeGet(horoscopes, 'collective_message', ''));
  const manifestationFocus = safeGet(horoscopes, 'manifestation_focus', '');
  const timingWisdom = safeGet(horoscopes, 'timing_wisdom', '');
  const imagePrompt = safeGet(horoscopes, 'cosmic_image_prompt', 'Urban setting. Photorealistic. Quiet, heavy mood. No text.');

  // === THE MODERN BLOG POST ===
  let blogContent = `# The Daily Read - ${today}\n\n`;
  blogContent += `## ✨ The Vibe Today\n${generalTheme}\n\n`;

  if (collectiveMessage) {
    blogContent += `## 🌟 Collective Reality Check\n${collectiveMessage}\n\n`;
  }

  if (manifestationFocus) {
    blogContent += `## 🎯 Do This Today\n${manifestationFocus}\n\n`;
  }

  if (timingWisdom) {
    blogContent += `## ⏳ Timing\n${timingWisdom}\n\n`;
  }

  blogContent += `## Your Personal Read\n\n`;

  signs.forEach(sign => {
    const signName = sign.charAt(0).toUpperCase() + sign.slice(1);
    const emoji = getSignEmoji(sign);
    const reading = safeGet(horoscopes, sign, `Check your chart for today's energy.`);
    blogContent += `### ${emoji} ${signName}\n${reading}\n\n`;
  });

  // === MODERN SOCIAL MEDIA POST ===
  let socialContent = `✨ ${today} - The Daily Read ✨\n\n`;
  socialContent += `🔮 ${generalTheme}\n\n`;

  if (collectiveMessage) {
    socialContent += `🎯 ${collectiveMessage}\n\n`;
  }

  socialContent += `#Astrology #Tarot #DailyHoroscope #Healing #CosmicEnergy`;

  // === INSTAGRAM STORY CONTENT ===
  const storyContent = {
    slide1: {
      text: `TODAY'S VIBE\n\n${generalTheme}`,
      background: "cosmic dark"
    },
    slide2: {
      text: collectiveMessage || manifestationFocus,
      background: "grainy dark"
    },
    slide3: {
      text: `THE FULL READ IS LIVE\n\nAll 12 signs. No fluff.\nJust the truth.\n\nLink in bio 🔮`,
      background: "mystical purple"
    }
  };

  items.push({
    json: {
      // Core formatted content
      blog_content: blogContent,
      social_media_post: socialContent,
      instagram_story: storyContent,

      // Today's lens (rides through to the parser, storage, and dashboard)
      nakshatra_name: seed.nakshatra_name || '',
      nakshatra_translation: seed.nakshatra_translation || '',
      nakshatra_lens: seed.nakshatra_lens || '',
      tithi_name: seed.tithi_name || '',

      // Metadata
      manifestation_focus: manifestationFocus,
      collective_message: collectiveMessage,

      // Raw data
      individual_horoscopes: horoscopes,
      date: today,
    }
  });
}

return items;

// Comprehensive Content Parser - Fixed & Optimized
const items = [];

try {
  const allInputs = $input.all();

  let dailyContent = null;
  let weeklyContent = null;
  let elementContent = null;

  const parseClaudeResponse = (text) => {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end !== -1) {
      return JSON.parse(text.substring(start, end + 1));
    }
    return JSON.parse(text);
  };

  for (const input of allInputs) {
    const data = input.json;
    if (data.blog_content || data.social_media_post || data.individual_horoscopes) {
      dailyContent = data;
      continue;
    }
    const blocks = Array.isArray(data.content)
      ? data.content.filter((b) => b && b.type === 'text' && typeof b.text === 'string').map((b) => b.text)
      : [];
    const parseable = (t) => {
      try {
        const s = t.indexOf('{');
        const e = t.lastIndexOf('}');
        if (s === -1 || e <= s) return false;
        JSON.parse(t.substring(s, e + 1));
        return true;
      } catch (err) { return false; }
    };
    const bestText = [blocks.join(''), ...[...blocks].sort((a, b) => b.length - a.length)].find(parseable) || null;
    if (bestText) {
      const text = bestText;
      if (text.includes('"weekly_theme"') || text.includes('"cosmic_energy"')) {
        try { weeklyContent = parseClaudeResponse(text); } catch (e) {}
      } else if (text.includes('"fire_signs"') || text.includes('"manifestation_posts"')) {
        try { elementContent = parseClaudeResponse(text); } catch (e) {}
      }
    } else if (data.weekly_theme && !weeklyContent) {
      weeklyContent = data;
    } else if (data.fire_signs && !elementContent) {
      elementContent = data;
    }
  }

  // Recompose element messages from schema-enforced hook/body/predictions.
  // (Separate required fields make hook-only output grammatically impossible.)
  if (elementContent) {
    const compose = (el, isAir) => {
      if (!el || el.message) return el;
      const hook = String(el.hook || '').trim();
      const body = isAir && Array.isArray(el.predictions)
        ? el.predictions.map((x) => '- ' + String(x).replace(/^[-\s]+/, '')).join('\n')
        : String(el.body || '').trim();
      return { ...el, message: body ? hook + '\n\n' + body : hook };
    };
    elementContent.fire_signs = compose(elementContent.fire_signs, false);
    elementContent.earth_signs = compose(elementContent.earth_signs, false);
    elementContent.air_signs = compose(elementContent.air_signs, true);
    elementContent.water_signs = compose(elementContent.water_signs, false);
  }

  const dataSourceFlags = {
    daily: !!dailyContent,
    weekly: !!weeklyContent,
    element: !!elementContent,
    interactive: !!elementContent?.manifestation_posts
  };

  const safeGet = (obj, path, fallback = '') => {
    try { return path.split('.').reduce((current, key) => current && current[key], obj) || fallback; } catch (e) { return fallback; }
  };

  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  function getSignEmoji(sign) {
    const emojis = { aries: '♈', taurus: '♉', gemini: '♊', cancer: '♋', leo: '♌', virgo: '♍', libra: '♎', scorpio: '♏', sagittarius: '♐', capricorn: '♑', aquarius: '♒', pisces: '♓' };
    return emojis[sign] || '⭐';
  }

  const signs = ['aries', 'taurus', 'gemini', 'cancer', 'leo', 'virgo', 'libra', 'scorpio', 'sagittarius', 'capricorn', 'aquarius', 'pisces'];

  // === COMPREHENSIVE BLOG POST ===
  // Use the Daily node's excellent formatting (which includes Panchangam) as the base
  let comprehensiveBlog = dailyContent?.blog_content ? dailyContent.blog_content + '\n\n' : `# Complete Cosmic Guidance - ${today}\n\n`;

  if (weeklyContent) {
    comprehensiveBlog += `--- \n\n## 🌟 This Week's Cosmic Story\n`;
    if (weeklyContent.weekly_theme) comprehensiveBlog += `${weeklyContent.weekly_theme}\n\n`;
    if (weeklyContent.collective_message) comprehensiveBlog += `**Universal Message:** ${weeklyContent.collective_message}\n\n`;

    comprehensiveBlog += `## Weekly Detailed Forecasts\n\n`;

    signs.forEach(sign => {
      // FIX: Handle Claude's tendency to nest the signs under a "signs" object
      const signData = weeklyContent.signs?.[sign] || weeklyContent[sign];

      if (signData && typeof signData === 'object') {
        const signName = sign.charAt(0).toUpperCase() + sign.slice(1);
        const emoji = getSignEmoji(sign);
        comprehensiveBlog += `### ${emoji} ${signName} - Weekly Outlook\n\n`;
        comprehensiveBlog += `**Cosmic Energy:** ${safeGet(signData, 'cosmic_energy', '')}\n\n`;
        comprehensiveBlog += `**Heart Guidance:** ${safeGet(signData, 'heart_guidance', '')}\n\n`;
        comprehensiveBlog += `**Life Purpose:** ${safeGet(signData, 'life_purpose', '')}\n\n`;
        comprehensiveBlog += `**Spiritual Insight:** ${safeGet(signData, 'spiritual_insight', '')}\n\n`;
        comprehensiveBlog += `**Lucky Moments:** ${safeGet(signData, 'lucky_moments', '')}\n\n`;
      }
    });
  }

  // === SOCIAL MEDIA MASTER POST ===
  // Prioritize the nicely formatted daily social post
  let masterSocialPost = dailyContent?.social_media_post ? dailyContent.social_media_post : `✨ ${today} - Complete Cosmic Guidance ✨\n\n`;

  // === ELEMENT & MANIFESTATION POSTS ===
  let elementPosts = {};
  if (elementContent) {
    ['fire_signs', 'earth_signs', 'air_signs', 'water_signs'].forEach(element => {
      if (elementContent[element]) {
        elementPosts[element] = {
          message: safeGet(elementContent[element], 'message', ''),
          call_to_action: safeGet(elementContent[element], 'call_to_action', ''),
          spiritual_practice: safeGet(elementContent[element], 'spiritual_practice', '')
        };
      }
    });
  }

  let manifestationPosts = [];
  if (elementContent?.manifestation_posts) {
    manifestationPosts = elementContent.manifestation_posts.map(post => ({
      theme: post.theme || 'manifestation',
      content: post.post || '',
      call_to_action: post.call_to_action || '',
      timing: post.timing || ''
    }));
  }

  // === INSTAGRAM STORIES ===
  let instagramStories = dailyContent?.instagram_story ? Object.values(dailyContent.instagram_story).map((s, i) => ({slide: i+1, ...s})) : [];

  // Add Weekly to Instagram Stories if it exists
  if (weeklyContent?.weekly_theme) {
    instagramStories.push({
      slide: instagramStories.length + 1,
      type: 'weekly_theme',
      text: `THIS WEEK'S ENERGY\n\n${weeklyContent.weekly_theme}`,
      background: 'mystical_purple'
    });
  }

  // --- CLEANUP DUPLICATES ---
  // To prevent the final JSON from being massive and duplicated,
  // we strip the pre-formatted strings out of the nested `daily_content` object,
  // keeping only the raw data there since the formatted versions are now at the root level.
  let cleanDailyData = null;
  if (dailyContent) {
      cleanDailyData = { ...dailyContent };
      delete cleanDailyData.blog_content;
      delete cleanDailyData.social_media_post;
      delete cleanDailyData.video_script;
      delete cleanDailyData.instagram_story;
      delete cleanDailyData.twitter_thread;
      delete cleanDailyData.reel_manifestation; // lives at top-level reel_scripts
  }

  const comprehensiveOutput = {
    data_sources: dataSourceFlags,
    generation_timestamp: new Date().toISOString(),
    content_quality: 'Premium astrology content with comprehensive integration',
    daily_content_raw: cleanDailyData || {},
    weekly_content_raw: weeklyContent || {},
    element_content_raw: elementContent || {},
    comprehensive_blog: comprehensiveBlog,
    master_social_post: masterSocialPost,
    element_posts: elementPosts,
    manifestation_posts: manifestationPosts,
    instagram_stories: instagramStories,

    // v8.5: spoken reel scripts for the Remotion pipeline (null-safe \u2014 dashboard
    // buttons disable themselves when a script is missing)
    reel_scripts: {
      manifestation: dailyContent?.reel_manifestation || null,
      elements: (() => {
        const r = elementContent?.reel_elements;
        if (!r || typeof r !== 'object') return null;
        const need = ['hook', 'fire', 'earth', 'air', 'water', 'cta', 'caption'];
        return need.every((k) => typeof r[k] === 'string' && r[k].trim()) ? r : null;
      })(),
    },

    // Today's lens — used by the dashboard for nakshatra-branded eyebrows
    nakshatra_name: dailyContent?.nakshatra_name || '',
    nakshatra_translation: dailyContent?.nakshatra_translation || '',
    nakshatra_lens: dailyContent?.nakshatra_lens || '',
    tithi_name: dailyContent?.tithi_name || '',
    date: today,
    total_content_pieces: Object.keys(elementPosts).length + manifestationPosts.length + instagramStories.length + 6,
    content_analytics: {
      blog_word_count: comprehensiveBlog.split(' ').length,
      social_character_count: masterSocialPost.length,
      element_targeting: Object.keys(elementPosts).length > 0,
      manifestation_content: manifestationPosts.length > 0,
      reel_scripts_ready: !!dailyContent?.reel_manifestation && !!elementContent?.reel_elements
    }
  };

  items.push({ json: comprehensiveOutput });

} catch (error) {
  items.push({ json: { error: 'Comprehensive parsing failed', error_details: error.message, stack: error.stack } });
}

return items;

