// Cosmic Seed — derives today's content lens from real Panchangam data,
// rotates manifestation themes, and summarizes yesterday to prevent repetition.

const NAKSHATRAS = {
  ashwini: { name: 'Ashwini', translation: "The Healer's Spark", lens: 'fast fresh starts, recovering quicker than expected, acting before overthinking kicks in' },
  bharani: { name: 'Bharani', translation: 'The Bearer', lens: 'carrying heavy things, endurance, noticing what you are holding that was never yours to hold' },
  krittika: { name: 'Krittika', translation: 'The Blade', lens: 'sharp honesty, cutting away dead weight, saying the thing directly' },
  rohini: { name: 'Rohini', translation: 'The Growth Star', lens: 'slow stubborn growth, tending what is already planted instead of starting over' },
  mrigashirsha: { name: 'Mrigashirsha', translation: 'The Seeker', lens: 'restlessness, the difference between healthy curiosity and chasing what avoids you' },
  ardra: { name: 'Ardra', translation: 'The Storm', lens: 'letting the mess happen, breakdown before clarity, crying it out and moving on' },
  punarvasu: { name: 'Punarvasu', translation: 'The Return', lens: 'second chances, coming back to yourself, repairing without shame' },
  pushya: { name: 'Pushya', translation: 'The Nourisher', lens: 'what actually feeds you versus what just fills time, letting yourself be cared for' },
  ashlesha: { name: 'Ashlesha', translation: 'The Serpent', lens: 'entanglement and control, unwinding manipulative dynamics, quiet self-protection' },
  magha: { name: 'Magha', translation: 'The Throne', lens: 'claiming your seat, family patterns, authority you keep apologizing for' },
  purvaphalguni: { name: 'Purva Phalguni', translation: 'The Pleasure Seat', lens: 'rest and enjoyment without guilt, softness as strength' },
  uttaraphalguni: { name: 'Uttara Phalguni', translation: 'The Contract', lens: 'commitments, the agreements you keep with yourself, showing up when it is boring' },
  hasta: { name: 'Hasta', translation: 'The Hand', lens: 'small precise moves, doing it yourself, skill over luck' },
  chitra: { name: 'Chitra', translation: 'The Jewel', lens: 'being seen, image versus substance, building something worth looking at' },
  swati: { name: 'Swati', translation: 'The Wind', lens: 'independence, bending without breaking, standing alone comfortably' },
  vishakha: { name: 'Vishakha', translation: 'The Forked Path', lens: 'focus, choosing one goal and dropping the backup plans' },
  anuradha: { name: 'Anuradha', translation: 'The Loyal Friend', lens: 'who actually shows up for you, devotion, honest friendship audits' },
  jyeshtha: { name: 'Jyeshtha', translation: 'The Elder', lens: 'outgrowing old roles, being the responsible one, protecting your peace' },
  mula: { name: 'Mula', translation: 'The Root', lens: 'getting to the bottom of it, pulling problems up by the root, honest endings' },
  purvaashadha: { name: 'Purva Ashadha', translation: 'The Invincible', lens: 'momentum, declaring instead of hinting, early confidence' },
  uttaraashadha: { name: 'Uttara Ashadha', translation: 'The Final Victory', lens: 'what endures, integrity when nobody watches, lasting wins over quick ones' },
  shravana: { name: 'Shravana', translation: 'The Listener', lens: 'listening more than talking, hearing what people are actually saying' },
  dhanishta: { name: 'Dhanishta', translation: 'The Drum', lens: 'timing and rhythm, money in motion, knowing when to move' },
  shatabhisha: { name: 'Shatabhisha', translation: 'The Hundred Healers', lens: 'privacy, healing in the dark, solitude that repairs instead of isolates' },
  purvabhadrapada: { name: 'Purva Bhadrapada', translation: 'The Fire Walker', lens: 'facing the uncomfortable thing directly, intensity with a purpose' },
  uttarabhadrapada: { name: 'Uttara Bhadrapada', translation: 'The Deep Water', lens: 'calm depth, the long view, staying steady while others spiral' },
  revati: { name: 'Revati', translation: 'The Shepherd', lens: 'finishing what you started, safe passage, guiding without carrying' },
};

const THEME_POOL = [
  { key: 'life_purpose', angle: 'claiming the actual path instead of the approved one; stop performing a life you do not want' },
  { key: 'abundance', angle: 'money and self-worth; what you undercharge, tolerate, or refuse to ask for' },
  { key: 'love_connection', angle: 'relationship honesty; what stays, what goes, and what you keep renegotiating' },
  { key: 'personal_growth', angle: 'the quiet progress nobody claps for; proof you are not who you were' },
  { key: 'friendship_audit', angle: 'which friendships feed you and which ones you maintain out of guilt' },
  { key: 'rest_and_recovery', angle: 'rest as a decision, not a collapse; what you refuse to put down' },
  { key: 'comparison_trap', angle: 'measuring your life against strangers; getting your eyes back on your own paper' },
  { key: 'self_trust', angle: 'keeping promises to yourself; your track record is better than your anxiety says' },
  { key: 'courage_at_work', angle: 'saying the number, asking for the role, disagreeing out loud' },
  { key: 'family_boundaries', angle: 'old family roles you have outgrown; love without self-erasure' },
];

// ── Nakshatra lookup (normalized, fuzzy fallback) ──
const pk = $('ProKerala Panchangam').first().json;
const rawNak = String(pk?.data?.nakshatra?.[0]?.name || '').toLowerCase().replace(/[^a-z]/g, '');
let nak = NAKSHATRAS[rawNak];
if (!nak && rawNak.length >= 4) {
  const hit = Object.keys(NAKSHATRAS).find(k => k.startsWith(rawNak.slice(0, 5)) || rawNak.startsWith(k.slice(0, 5)));
  if (hit) nak = NAKSHATRAS[hit];
}
if (!nak) nak = { name: '', translation: '', lens: 'boundaries, honest self-assessment, and doing the small brave thing today' };
const tithi = pk?.data?.tithi?.[0]?.name || '';

// ── Rotate 4 of 10 themes deterministically by day-of-year ──
const now = new Date();
const doy = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
const themes = [0, 1, 2, 3].map(i => THEME_POOL[(doy * 3 + i * 3) % THEME_POOL.length]);
const themesBlock = themes.map((t, i) => `${i + 1}. theme key: "${t.key}" — angle: ${t.angle}`).join('\n');

// ── Yesterday summary from Supabase (input of this node) ──
let avoid = 'No record of yesterday. Just make today feel fresh and specific.';
try {
  const rows = $input.all().map(i => i.json).filter(Boolean);
  const row = rows.find(r => r.payload);
  let pl = row?.payload;
  if (typeof pl === 'string') pl = JSON.parse(pl);
  if (pl) {
    const bits = [];
    const ov = pl.daily_content_raw?.individual_horoscopes?.cosmic_overview;
    if (ov) bits.push('Overview: ' + String(ov).slice(0, 160));
    (pl.manifestation_posts || []).forEach(p => {
